/* ============================================================================
   Deploy-Remote.sql
   Self-contained deployment script -- embeds the compiled MailboxReaderClr.dll
   directly as a hex literal, so this can be run against ANY SQL Server
   (local or remote) with no need to copy the DLL to that machine first, and
   no dependency on OPENROWSET/BULK filesystem access. Just connect (SSMS,
   Azure Data Studio, or sqlcmd) and run this whole script.

   Requires SQL Server 2017 CU12+ / SQL Server 2019+ (sys.sp_add_trusted_assembly).
   Requires sysadmin (or equivalent: ALTER SETTINGS + CONTROL SERVER) rights
   on the target instance.

   Generated from MailboxReaderClr v1.0.1 -- bin\Release\net472\MailboxReaderClr.dll
   (v1.0.1 drops the System.Web.Extensions/JavaScriptSerializer dependency in
   favor of a hand-rolled JSON parser, so this is the ONLY assembly SQL Server
   needs to know about -- no more "assembly ... is not present" errors.)
   ============================================================================ */

-- 1) Enable CLR (leave 'clr strict security' ON -- default and recommended)
EXEC sp_configure 'show advanced options', 1;
RECONFIGURE;
EXEC sp_configure 'clr enabled', 1;
RECONFIGURE;
GO

-- 2) Trust + register the assembly from embedded bytes (no file path needed)
DECLARE @AssemblyBytes VARBINARY(MAX) = ;
DECLARE @Hash VARBINARY(64) = HASHBYTES('SHA2_512', @AssemblyBytes);

EXEC sys.sp_add_trusted_assembly @hash = @Hash, @description = N'MailboxReaderClr.dll v1.0.1';

CREATE ASSEMBLY MailboxReaderClr
FROM @AssemblyBytes
WITH PERMISSION_SET = EXTERNAL_ACCESS;
GO

-- 3) Create the stored procedure wrapper
CREATE PROCEDURE dbo.usp_ReadMailbox
    @TenantId      NVARCHAR(100),
    @ClientId      NVARCHAR(100),
    @ClientSecret  NVARCHAR(200) = NULL,
    @MailboxUpn    NVARCHAR(320),
    @Password      NVARCHAR(200) = NULL,
    @FolderName    NVARCHAR(100) = 'inbox',
    @Top           INT = 25,
    @UnreadOnly    BIT = 0
AS EXTERNAL NAME MailboxReaderClr.[MailboxReaderClr.MailReader].ReadMailbox;
GO

/* ============================================================================
   Example usage -- see README.md / Deploy.sql for the full parameter reference
   ============================================================================ */

EXEC dbo.usp_ReadMailbox
    @TenantId     = 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx',
    @ClientId     = 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx',
    @ClientSecret = 'your-client-secret-value',
    @MailboxUpn   = 'serviceaccount@yourdomain.com',
    @Top          = 25;

/* ============================================================================
   To remove everything later:
   DROP PROCEDURE dbo.usp_ReadMailbox;
   DROP ASSEMBLY MailboxReaderClr;
   -- (find the hash via: SELECT * FROM sys.trusted_assemblies)
   EXEC sys.sp_drop_trusted_assembly @hash = <hash from sys.trusted_assemblies>;
   ============================================================================ */